{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C17"],
      "claim": "Rilzabrutinib, which shares the same aminopyrazolopyrimidine-phenoxyphenyl core and acrylamide-piperidine warhead as the query, has an absolute oral bioavailability of only 6.4% in healthy subjects, with other estimates near 4.7%, indicating that this scaffold is associated with low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Acalabrutinib, a related BTK inhibitor with a similar aminopyrimidine hinge-binding core but different substituents, has an absolute oral bioavailability of 25% in humans, showing that some close analogs can exceed the 20% threshold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Predicted low because the highest-similarity evidence (rilzabrutinib, Morgan 0.52) shows very low human F (~5%) for the same core; the query is essentially the ibrutinib scaffold, which is known to have low oral bioavailability, and the less similar analogs with higher F are too distant to override.",
  "evidence_gaps": [
    "No direct human absolute bioavailability record for the exact query molecule is present in the supplied evidence set.",
    "The effect of removing rilzabrutinib's bulky substituent and fluorine on F is not directly measured, but the shared core and known ibrutinib pharmacokinetics support low bioavailability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

